4:export const STROKES = ["Power", "Exhaust", "Intake", "Compression"];
9:export const pistonPos = (alpha, r, l) => r * Math.cos(alpha) + Math.sqrt(l * l - (r * Math.sin(alpha)) ** 2);
13:export function layout(order) {
22:export const pinAngle = (lay, i, lean = 0) => mod(lean + lay.offset[i], TAU);
24:export const phaseOf = (theta, offset) => mod(theta - offset, CYCLE);
25:export const strokeOf = ph => STROKES[Math.floor(mod(ph, CYCLE) / Math.PI)];
28:export const firingOrder = lay => lay.offset.map((o, i) => [o, i + 1]).sort((a, b) => a[0] - b[0]).map(p => p[1]);
31:export const bumpLift = (ph, open, close, max) => (ph > open && ph < close) ? Math.sin(Math.PI * (ph - open) / (close - open)) * max : 0;
34:export const TIMING = {
46:export function valveLifts(ph, kind, max) {
52:export const flashOf = ph => (ph < Math.PI ? Math.max(0, 1 - (ph / Math.PI) * 2.2) : 0);
53:export const injecting = ph => ph > TIMING.injection[0] && ph < TIMING.injection[1];
54:export const injectingDiesel = ph => ph > TIMING.diesel[0] || ph < TIMING.diesel[1];
