  const t = layout([1, 5, 3, 6, 2, 4]).throwA.map(a => Math.round(a * 180 / Math.PI) % 360);
  assert.equal(t[0], t[5]); assert.equal(t[1], t[4]); assert.equal(t[2], t[3]);
